package auth_test

import (
	"net/http"

	"github.com/go-chi/chi/v5"
	"github.com/pluff/pluff/engine/backend/go/internal/modulespec"
)

// Install registers this tatemono's compiled routes. Generated by the Go
// backend engine from the DSL build payload — do not edit by hand.
func Install(r chi.Router, svc modulespec.Services) {

	// Engine-owned auth routes are served dynamically by the fallback handler.
	r.Method(http.MethodGet, "/api/"+ModuleName+"/auth/*", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Fallback(w, req) }))
	r.Method(http.MethodPost, "/api/"+ModuleName+"/auth/*", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Fallback(w, req) }))
	r.Method(http.MethodDelete, "/api/"+ModuleName+"/auth/*", http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) { svc.Fallback(w, req) }))
}
